# concise candidate comparison for test: report all aligned consecutive intervals not on bbox perimeter
# Grid reconstructed from the user-provided test.
R=['111111111111111','111919991111911','111111111111911','111111111191111','111911111191111','111111111191111','111911111191111','111911111111111','111111111191111','111111111111111','111111111191111','111911111111111','111911111111111','111111111191111','111111111191111','111911111191111','111911111191111','111911111191111','111911111119111','111911111111111','111919119911111']
g=[list(map(int,x)) for x in R]
coords=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==9]
r0,r1=min(r for r,c in coords),max(r for r,c in coords); c0,c1=min(c for r,c in coords),max(c for r,c in coords)
inside=[]
for r,row in enumerate(g):
 m=[c for c,x in enumerate(row) if x==9]
 for a,b in zip(m,m[1:]):
  for c in range(a+1,b):
   if row[c]==1 and r not in (r0,r1) and c not in (c0,c1): inside.append((r,c))
for c in range(len(g[0])):
 m=[r for r,row in enumerate(g) if row[c]==9]
 for a,b in zip(m,m[1:]):
  for r in range(a+1,b):
   if g[r][c]==1 and r not in (r0,r1) and c not in (c0,c1): inside.append((r,c))
print({'bbox':(r0,r1,c0,c1),'interior_interval_additions':inside})

